// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadDancingScript = makeLoadFont('DancingScript');

// Load 1920s script font
const { fontFamily: scriptFontFamily } = loadDancingScript();



export type VintageTitleCardProps = Record<string, any>;

const VintageTitleCard: React.FC<VintageTitleCardProps> = ({
  backgroundColor = "#070707",
  transparentBackground = false,
  durationInSeconds = 5,
  titleCardText = "A Tale of Two Cities",
  textColor = "#f4f4f0",
  flickerIntensity = 0.6,
  showVintageBorder = true,
}) => {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Safety logic for transparent background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timing
  const totalFrames = durationInSeconds * fps;
  const fadeDuration = Math.min(30, Math.floor(totalFrames / 4));

  // Fade In
  const fadeOpacity = interpolate(frame, [0, fadeDuration], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Fade Out
  const outroOpacity = interpolate(
    frame,
    [totalFrames - fadeDuration, totalFrames],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const currentOpacity = fadeOpacity * outroOpacity;

  // Vintage Dolly Push Effect (Slow Scale)
  const scale = interpolate(frame, [0, totalFrames], [1, 1.05]);

  // Jitter (Physical film unsteadiness)
  const jitterX = interpolate(random(`jitter-x-${frame}`), [0, 1], [-2, 2]) * flickerIntensity;
  const jitterY = interpolate(random(`jitter-y-${frame}`), [0, 1], [-2, 2]) * flickerIntensity;

  // Exposure Flicker (Brightness changes)
  const brightnessFlicker = interpolate(random(`flicker-${frame}`), [0, 1], [0.9, 1.1]);

  // Film Scratches Logic
  // Change scratch patterns every 3 frames for a choppy, old-timey feel
  const scratchSeed = Math.floor(frame / 3);
  
  // Scratch 1
  const scratchX1 = random(`s1-${scratchSeed}`) * width;
  const scratchOpacity1 = random(`o1-${scratchSeed}`) > 0.5 ? 0.4 * flickerIntensity : 0;
  
  // Scratch 2
  const scratchX2 = random(`s2-${scratchSeed}`) * width;
  const scratchOpacity2 = random(`o2-${scratchSeed}`) > 0.7 ? 0.3 * flickerIntensity : 0;

  // Scratch 3 (Thick scratch)
  const scratchX3 = random(`s3-${scratchSeed}`) * width;
  const scratchOpacity3 = random(`o3-${scratchSeed}`) > 0.85 ? 0.15 * flickerIntensity : 0;

  // Dynamic Sizing
  const borderThickness = Math.max(2, Math.min(width, height) * 0.008);
  const fontSize = Math.min(width, height) * 0.12;
  const textLines = titleCardText.split('\n');

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Main Content Layer */}
      <AbsoluteFill
        style={{
          opacity: currentOpacity,
          transform: `translate(${jitterX}px, ${jitterY}px) scale(${scale})`,
          filter: `brightness(${brightnessFlicker})`,
          justifyContent: "center",
          alignItems: "center",
          padding: "10%",
        }}
      >
        {/* Vintage Ornate/Double Border */}
        {showVintageBorder && (
          <div
            style={{
              position: "absolute",
              top: "5%",
              bottom: "5%",
              left: "6%",
              right: "6%",
              border: `${borderThickness}px double ${textColor}`,
              opacity: 0.7,
              borderRadius: "16px",
              pointerEvents: "none",
            }}
          />
        )}

        {/* Script Text */}
        <div
          style={{
            fontFamily: scriptFontFamily,
            color: textColor,
            fontSize: fontSize,
            textAlign: "center",
            lineHeight: 1.3,
            display: "flex",
            flexDirection: "column",
            gap: "10px",
            zIndex: 10,
            textShadow: `0px 0px ${fontSize * 0.08}px rgba(255, 255, 255, 0.3)`, // Light bleed effect
          }}
        >
          {textLines.map((line, i) => (
            <span key={i} style={{ transition: "none" }}>
              {line}
            </span>
          ))}
        </div>
      </AbsoluteFill>

      {/* Vignette Overlay (Darkened Edges) */}
      <AbsoluteFill
        style={{
          background: "radial-gradient(circle at center, transparent 35%, rgba(0,0,0,0.85) 100%)",
          pointerEvents: "none",
        }}
      />

      {/* Film Scratches Overlay */}
      {flickerIntensity > 0 && (
        <AbsoluteFill style={{ pointerEvents: "none", opacity: currentOpacity }}>
          <div
            style={{
              position: "absolute",
              left: scratchX1,
              top: 0,
              bottom: 0,
              width: "1px",
              backgroundColor: textColor,
              opacity: scratchOpacity1,
            }}
          />
          <div
            style={{
              position: "absolute",
              left: scratchX2,
              top: 0,
              bottom: 0,
              width: "2px",
              backgroundColor: textColor,
              opacity: scratchOpacity2,
            }}
          />
          <div
            style={{
              position: "absolute",
              left: scratchX3,
              top: 0,
              bottom: 0,
              width: "4px",
              backgroundColor: textColor,
              opacity: scratchOpacity3,
            }}
          />
        </AbsoluteFill>
      )}
    </AbsoluteFill>
  );
};

export default VintageTitleCard;